package store

import (
	"context"
	"fmt"
	"time"
)

// Memory is one brain_facts row projected for the read model.
type Memory struct {
	FactID          string
	Text            string
	Kind            string
	Status          string
	SupersededBy    string
	CreatedBy       string
	CreatedByHandle string
	LastActionBy    string
	Paths           []string
	Locus           []string
	CreatedAt       time.Time
	UpdatedAt       time.Time
}

// DefaultMemoriesLimit is Memories' page size when limit is unset or out of
// range. MaxMemoriesLimit is the largest accepted page size. Exported so
// callers (the HTTP handler's full-page detection) share this single
// definition instead of duplicating the clamp rule.
const (
	DefaultMemoriesLimit = 50
	MaxMemoriesLimit     = 200
)

// ClampMemoriesLimit applies Memories' limit clamp: <=0 or >MaxMemoriesLimit
// becomes DefaultMemoriesLimit.
func ClampMemoriesLimit(limit int) int {
	if limit <= 0 || limit > MaxMemoriesLimit {
		return DefaultMemoriesLimit
	}
	return limit
}

// Memories lists brain_facts for repoID/branch, optionally full-text filtered
// by q, ordered newest-first. before/beforeFactID form a keyset cursor over
// (updated_at DESC, fact_id ASC): zero before + empty beforeFactID is page 1.
// The tuple predicate (not a plain updated_at cutoff) is required because one
// Advance stamps every row it touches with the same transaction-local now().
func (s *Store) Memories(ctx context.Context, repoID, branch, q string, limit int, before time.Time, beforeFactID string) ([]Memory, error) {
	limit = ClampMemoriesLimit(limit)
	args := []any{repoID, branch}
	where := `repo_id = $1 AND branch = $2`
	if !before.IsZero() {
		args = append(args, before, beforeFactID)
		n := len(args)
		where += fmt.Sprintf(` AND (updated_at < $%d OR (updated_at = $%d AND fact_id > $%d))`, n-1, n-1, n)
	}
	if q != "" {
		args = append(args, q)
		// q filters; it does not re-order. Ranking by ts_rank here would break
		// the keyset above — rank isn't monotonic with (updated_at, fact_id),
		// so cursored pages would silently drop matching rows, not just
		// reorder them. Searches stay recency-ordered and pagination complete.
		where += fmt.Sprintf(` AND tsv @@ websearch_to_tsquery('english', $%d)`, len(args))
	}
	args = append(args, limit)
	rows, err := s.pool.Query(ctx, fmt.Sprintf(`
		SELECT fact_id, text, kind, status, superseded_by, paths, locus, created_by, created_by_handle, last_action_by, created_at, updated_at
		FROM brain_facts WHERE %s ORDER BY updated_at DESC, fact_id ASC LIMIT $%d`, where, len(args)), args...)
	if err != nil {
		return nil, fmt.Errorf("store: memories: %w", err)
